#nullable enable // autogenerated

using System.Collections.Generic;
using System.Linq;
using PVZEngine;
using UnityEngine;

namespace MVZ2.Resources
{
    public class TextureResolver : ResourceResolver<NamespaceID, Texture2D> 
    {
        protected override List<NamespaceID> BuildCandidateKeys(NamespaceID key, ResourceContext context)
        {
            var list = new List<NamespaceID>();
            list.Add(key);
            return list;
        }
    }
}
